css:
.tm-cut h2 { margin: 0 0 6px; }
.tm-cut table { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
.tm-cut th, .tm-cut td { border: 1px solid #ccc; padding: 4px 6px; }
.tm-cut th { background: #f3f3f3; text-align: left; }
.tm-cut .num { text-align: right; }
.tm-cut .kpi { display: inline-block; border: 1px solid #ccc; border-radius: 4px; padding: 6px 10px; margin: 0 8px 8px 0; }
.tm-cut .kpi b { display: block; font-size: 16px; }
.tm-cut svg { width: 26mm; height: 26mm; float: right; }
